// Edit these values once. Categories live in Return Category List, so the AI tool and the check read one list.
const SETTINGS = {
  sheet_url: 'YOUR_GOOGLE_SHEET_URL',          // tabs Enquiries, Review, Spam, Errors with these row-1 columns:
  //   Enquiries: received_at, name, email, company, category, priority, urgency, confidence, summary, message
  //   Review: received_at, name, email, company, suggested, check_notes, summary, message
  //   Spam: received_at, email, confidence, summary, message
  //   Errors: logged_at, email, step, error
  tabs: { enquiries: 'Enquiries', review: 'Review', spam: 'Spam', errors: 'Errors' },
  alert_email: 'YOUR_ALERT_EMAIL',             // urgent enquiries, review requests and failures are emailed here
  slack_alerts: false,                         // true = also post urgent enquiries to Slack (add a Slack credential)
  slack_channel: '#leads',
  reply_drafts: false,                         // true = save an AI-written first reply as a Gmail DRAFT (never sent) for categories with draft_reply: true
  min_confidence: 0.6,                         // below this the enquiry goes to the Review tab
  min_spam_confidence: 0.8,                    // spam needs this much, otherwise a person checks it
  honeypot_field: 'website',                   // hidden form field people never fill in; '' turns it off
  max_message_chars: 4000,                     // longer messages are cut before they reach the AI
};
return $input.all().map((item) => ({ json: { ...item.json, cfg: SETTINGS } }));

// Reads the form (JSON or form-encoded), trims the fields and decides the route:
// invalid -> HTTP 400 (no valid email), bot -> quiet 200 (honeypot filled), ok -> triage.
return $input.all().map((item) => {
  const cfg = item.json.cfg;
  const body = item.json.body && typeof item.json.body === 'object' ? item.json.body : {};
  const clean = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
  const name = clean(body.name).slice(0, 200);
  const email = clean(body.email).toLowerCase().slice(0, 200);
  const company = clean(body.company).slice(0, 200);
  const message = String(body.message ?? '').trim().slice(0, Number(cfg.max_message_chars) || 4000);
  const honeypot = cfg.honeypot_field ? clean(body[cfg.honeypot_field]) : '';
  let error = '';
  if (!email) error = 'email is required';
  else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) error = 'email is not valid';
  else if (!message) error = 'message is required';
  const route = error ? 'invalid' : honeypot ? 'bot' : 'ok';
  const fingerprint = email + '|' + message.toLowerCase().replace(/\s+/g, ' ');
  return { json: { route, error, received_at: new Date().toISOString(), name, email, company, message, fingerprint, cfg } };
});

// The category must be one of the ids from Category List (the same list the agent's tool returned).
// Unknown ids, low confidence, unsure spam and AI errors go to the Review tab with the reason in check_notes.
const enquiries = $('Merge Enquiry with Categories').all();
const cats = $('Load Allowed Categories').first().json.categories || [];
const byId = Object.fromEntries(cats.map((c) => [c.id.toLowerCase(), c]));
return $input.all().map((item, n) => {
  const p = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const e = (enquiries[p && typeof p.item === 'number' ? p.item : n] || enquiries[n]).json;
  const cfg = e.cfg;
  const r = item.json.output || {};
  const aiError = item.json.error && !item.json.output ? String(item.json.error.message || item.json.error).slice(0, 200) : '';
  const picked = String(r.category || '').trim().toLowerCase();
  const cat = byId[picked];
  const c = Number(r.confidence);
  const conf = Number.isFinite(c) ? Math.max(0, Math.min(1, c)) : null;
  const urgency = ['high', 'normal', 'low'].includes(String(r.urgency).toLowerCase()) ? String(r.urgency).toLowerCase() : 'normal';
  const summary = String(r.summary || '').replace(/\s+/g, ' ').trim().slice(0, 240);
  let route = 'review', notes = '';
  if (aiError) notes = 'AI step failed: ' + aiError;
  else if (!cat) notes = picked ? `AI picked "${picked.slice(0, 60)}", which is not in Category List` : 'AI gave no category';
  else if (conf === null) notes = `No confidence score (suggested: ${cat.id})`;
  else if (conf < Number(cfg.min_confidence)) notes = `Low confidence ${conf.toFixed(2)} (suggested: ${cat.id})`;
  else if (cat.id === 'spam' && conf < Number(cfg.min_spam_confidence)) notes = `Possible spam, confidence ${conf.toFixed(2)}`;
  else if (cat.id === 'spam') route = 'spam';
  else route = cat.priority === 'high' || urgency === 'high' ? 'urgent' : 'normal';
  const category = route === 'review' ? 'needs_review' : cat.id;
  const who = e.name ? `${e.name} <${e.email}>` : e.email;
  const draft = String(r.reply_draft || '').trim();
  return { json: {
    received_at: e.received_at, name: e.name, email: e.email, company: e.company, message: e.message,
    category, suggested: cat ? cat.id : picked, priority: cat && route !== 'review' ? cat.priority : 'review', urgency,
    confidence: conf === null ? '' : conf, summary, check_notes: notes, route, ai_error: !!aiError,
    wants_draft: Boolean(cfg.reply_drafts && cat && cat.draft_reply && route !== 'review' && draft), reply_draft: draft,
    alert_subject: route === 'review' ? `Enquiry needs a look: ${who}` : `New ${category.replace(/_/g, ' ')} (${urgency} urgency): ${who}`,
    alert_text: `${who}${e.company ? ' from ' + e.company : ''}\nCategory: ${category}${notes ? '\nWhy review: ' + notes : ''}\nSummary: ${summary || '(none)'}\n\nMessage:\n${e.message}`,
    cfg,
  } };
});

