// Your categories. The AI agent reads this list through its tool and may only pick one of these ids.
// priority high = urgent alert (email, optional Slack). draft_reply = allowed to get a Gmail reply draft.
const CATEGORIES = [
  { id: 'sales_inquiry', description: 'Wants to buy, asks about pricing, a quote, a demo or a trial', priority: 'high', draft_reply: true },
  { id: 'support', description: 'Existing customer with a problem, bug, complaint or how-to question', priority: 'high', draft_reply: true },
  { id: 'partnership', description: 'Proposes a partnership, reseller deal, integration or co-marketing', priority: 'medium', draft_reply: true },
  { id: 'job_application', description: 'Applies for a job or internship, or sends a CV', priority: 'low', draft_reply: false },
  { id: 'spam', description: 'Unsolicited sales pitch, SEO or link offers, scams, gibberish', priority: 'none', draft_reply: false },
  { id: 'other', description: 'A real message that fits none of the categories above', priority: 'low', draft_reply: false },
];
return [{ json: { categories: CATEGORIES } }];
